// ─── History ───
function saveCopyHistory(product,versions){
  var history=[];
  try{history=JSON.parse(localStorage.getItem('qg_copy_history')||'[]');}catch(e){}
  history.unshift({time:new Date().toISOString(),product:product||(CopyConfig.customDay==='festival'?(CopyConfig.festivalName||'节气'):''),v1:versions[0],v2:versions[1],v3:versions[2]});
  if(history.length>20)history=history.slice(0,20);
  localStorage.setItem('qg_copy_history',JSON.stringify(history));
  renderCopyHistory();
}

function renderCopyHistory(){
  var el=document.getElementById('copyHistory');
  if(!el)return;
  var history=[];
  try{history=JSON.parse(localStorage.getItem('qg_copy_history')||'[]');}catch(e){}
  if(!history.length){el.innerHTML='<div style="padding:4px 0">暂无记录</div>';return;}
  var html='';
  history.forEach(function(h,i){
    html+='<div style="padding:6px 0;border-bottom:1px solid var(--border);cursor:pointer" onclick="loadCopyHistory('+i+')"><div style="font-size:10px;color:var(--text-muted)">'+h.time.substring(5,16).replace('T',' ')+'</div><div style="font-size:11px;color:var(--text)">'+h.product+'</div></div>';
  });
  el.innerHTML=html;
}

function clearCopyHistory(){
  if(!confirm('确定清空所有历史文案记录？'))return;
  localStorage.removeItem('qg_copy_history');
  renderCopyHistory();
  toast('🗑 历史已清空');
}

function loadCopyHistory(idx){
  var history=[];
  try{history=JSON.parse(localStorage.getItem('qg_copy_history')||'[]');}catch(e){}
  if(idx>=history.length)return;
  var h=history[idx];
  document.getElementById('copyV1').innerHTML=formatCopyDisplay(h.v1,'版本一','历史');document.getElementById("copyV1").parentElement.style.opacity="1";
  document.getElementById('copyV2').innerHTML=formatCopyDisplay(h.v2,'版本二','历史');document.getElementById("copyV2").parentElement.style.opacity="1";
  document.getElementById('copyV3').innerHTML=formatCopyDisplay(h.v3,'版本三','历史');document.getElementById("copyV3").parentElement.style.opacity="1";
  document.querySelectorAll('.copy-actions').forEach(function(a){a.style.display='flex';});
}

