function renderCardLib(){
  var el=document.getElementById('inspContent');
  var cats=getCardCats();
  var allCats=Object.keys(cats);
  var html='<div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:16px">'+
    '<span class="insp-pill active" onclick="filterCards(\'all\',this)" style="font-size:11px;padding:4px 12px;border-radius:20px;cursor:pointer;background:var(--brand);color:#fff">全部</span>';
  allCats.forEach(function(c){
    html+='<span class="insp-pill" onclick="filterCards(\''+c+'\',this)" style="font-size:11px;padding:4px 12px;border-radius:20px;cursor:pointer;background:var(--bg);color:var(--text-dim);border:1px solid var(--border)">'+c+'</span>';
  });
  html+='<span class="insp-pill" onclick="showCardModal()" style="font-size:11px;padding:4px 12px;border-radius:20px;cursor:pointer;background:var(--brand-light);color:var(--brand);border:1px dashed var(--brand);white-space:nowrap">➕ 添加</span></div><div id="cardGrid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px"></div>';
  el.innerHTML=html;
  filterCards('all');
}

var currentCardFilter='all';
function filterCards(cat,el){
  currentCardFilter=cat;
  if(el){
    document.querySelectorAll('.insp-pill').forEach(function(p){p.classList.remove('active');p.style.background='var(--bg)';p.style.color='var(--text-dim)';p.style.border='1px solid var(--border)';});
    el.classList.add('active');el.style.background='var(--brand)';el.style.color='#fff';el.style.border='none';
  }
  var grid=document.getElementById('cardGrid');
  var cats=getCardCats();
  var all=[];
  Object.keys(cats).forEach(function(c){
    if(cat==='all'||c===cat) all=all.concat(cats[c].map(function(p){return {phrase:p,cat:c};}));
  });
  var html='';
  all.forEach(function(item){
    var p=item.phrase;
    if(!p.trim())return; if(p.trim().length<2)return;
      html+='<div style="position:relative;background:#fff;border-radius:8px;padding:14px 12px;border:1px solid var(--border);font-size:14px;line-height:1.5;color:var(--text);display:flex;align-items:center;justify-content:center;text-align:center;min-height:50px;cursor:pointer;word-break:break-word;white-space:normal" onclick="navigator.clipboard.writeText(this.textContent);toast(\'📋 已复制\')" title="点击复制">'+p+'<span onclick="event.stopPropagation();delCardClick(this)" data-cat="'+item.cat+'" data-idx="'+encodeURIComponent(p)+'" style="position:absolute;top:2px;right:4px;font-size:10px;opacity:0.25;cursor:pointer" onmouseenter="this.style.opacity=0.7" onmouseleave="this.style.opacity=0.25" title="删除自定义花字">🗑</span></div>';
 });
  grid.innerHTML=html||'<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--text-dim)">无匹配</div>';
}

